import{_ as r,o as a,c as d,ag as e}from"./chunks/framework.CvZZEx4j.js";const u=JSON.parse('{"title":"界面总览","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ui-overview.md","filePath":"guide/ui-overview.md","lastUpdated":null}'),o={name:"guide/ui-overview.md"};function n(s,t,i,l,h,g){return a(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="界面总览" tabindex="-1">界面总览 <a class="header-anchor" href="#界面总览" aria-label="Permalink to &quot;界面总览&quot;">​</a></h1><h2 id="覆盖层结构" tabindex="-1">覆盖层结构 <a class="header-anchor" href="#覆盖层结构" aria-label="Permalink to &quot;覆盖层结构&quot;">​</a></h2><p>Galgame 覆盖层是插件的核心界面，它覆盖在 SillyTavern 的聊天区域之上，将 AI 输出渲染为视觉小说画面。</p><p>覆盖层由以下区域组成：</p><table tabindex="0"><thead><tr><th>区域</th><th>说明</th></tr></thead><tbody><tr><td><strong>背景层</strong></td><td>全屏背景图片，随剧情场景切换</td></tr><tr><td><strong>特效层</strong></td><td>PixiJS 粒子特效（雨、雪、雾等）</td></tr><tr><td><strong>立绘槽位</strong></td><td>左右两侧的角色立绘/Live2D 展示区域</td></tr><tr><td><strong>对话框</strong></td><td>底部半透明对话框，显示角色名和对话文本</td></tr><tr><td><strong>工具栏</strong></td><td>底部操作按钮区域</td></tr></tbody></table><h2 id="工具栏按钮" tabindex="-1">工具栏按钮 <a class="header-anchor" href="#工具栏按钮" aria-label="Permalink to &quot;工具栏按钮&quot;">​</a></h2><p>工具栏位于覆盖层底部，提供以下功能：</p><table tabindex="0"><thead><tr><th>按钮</th><th>功能</th></tr></thead><tbody><tr><td>⚙️ <strong>设置</strong></td><td>打开设置面板</td></tr><tr><td>📖 <strong>历史</strong></td><td>查看剧情回顾</td></tr><tr><td>🗺️ <strong>地图</strong></td><td>打开地图系统</td></tr><tr><td>🔊 <strong>BGM</strong></td><td>背景音乐播放/暂停</td></tr><tr><td>⏭️ <strong>下一步</strong></td><td>推进到下一段对话</td></tr><tr><td>🔲 <strong>全屏</strong></td><td>进入/退出全屏模式</td></tr></tbody></table><h2 id="打开和关闭覆盖层" tabindex="-1">打开和关闭覆盖层 <a class="header-anchor" href="#打开和关闭覆盖层" aria-label="Permalink to &quot;打开和关闭覆盖层&quot;">​</a></h2><ul><li><strong>打开</strong>：点击聊天区域右下角的 Galgame 按钮</li><li><strong>关闭</strong>：再次点击该按钮，或在覆盖层内按 <code>Esc</code></li></ul><h2 id="全屏模式" tabindex="-1">全屏模式 <a class="header-anchor" href="#全屏模式" aria-label="Permalink to &quot;全屏模式&quot;">​</a></h2><p>点击工具栏的 <strong>全屏</strong> 按钮，覆盖层将扩展至浏览器全屏，获得更沉浸的体验。</p><p>再次点击或按 <code>Esc</code> 可退出全屏。</p>',13)])])}const p=r(o,[["render",n]]);export{u as __pageData,p as default};
